from pathlib import Path
import json
root=Path(__file__).resolve().parent;tx=json.loads((root.parent/'fabric-youtube/HtR5m5VjaDQ/transcript.json').read_text())['transcript']
examples=[
 dict(id='category-to-family',window=[51,81],anchor='in a larger stack',teaching_job='Locate one product within a larger family, then distinguish audiences and roles',visual_family='perspective layered cards',entities=['Genie One','Genie Code','Genie Agents'],relationships=['belongs to product family','serves business users','serves technical users','serves both audiences'],states=['Established Genie One card','Existing card tilts and gains layers','Related product separates from family','Audience annotation appears','Third product is introduced with its role'],motion=['persist existing object','tilt plane','extrude layers','separate sibling','add attached annotation'],timing_policy='Family transformation begins with the larger-stack statement; distinguish products as their names and audiences are introduced',why='Preserve the known product while expanding the viewer’s mental model; position and annotations distinguish the siblings',reuse_rule='When explaining membership followed by distinctions among related entities, retain the established entity, expand its family, then label the distinctions. Perspective is a style choice, not a requirement of the word stack.',evidence='graphics-study/03-layered-cards.jpg'),
 dict(id='overview-to-subsystem',window=[220,245],anchor='On the modeled side',teaching_job='Decompose an established system and inspect one subsystem',visual_family='architecture master/detail',entities=['ontology overview','modeled ontology','metric views'],relationships=['subsystem of','contains component'],states=['Full overview with modeled side highlighted','Irrelevant regions dim','Camera moves into selected subsystem','First internal component appears'],motion=['change emphasis','pan and zoom inner world inside fixed viewport','reveal child component'],timing_policy='Focus the modeled side during the transition into its explanation; the measured camera move occurs around 234–236 seconds before metric views are named around 238 seconds',why='Show where the detail belongs before introducing internal components, while preserving spatial orientation',reuse_rule='When narration moves from a system to one of its parts, reuse the existing overview and focus that part before adding detail.',evidence='graphics-study/D2-architecture-camera.jpg'),
 dict(id='mechanism-and-integration',window=[600,625],anchor='data that lives',teaching_job='Explain how a system accesses external operational information',visual_family='connector network',entities=['third-party applications','data hub','live query','MCP connectors'],relationships=['connects to','queries live'],states=['Prior comparison clears','Data hub is established','External source icons and routes build','Query route and output appear','Integration category is added','Completed system holds during examples'],motion=['clear prior detail','persist hub','draw rounded branches','introduce sources','add category label','hold'],timing_policy='Establish the new source/mechanism while it is introduced; leave the built network visible as Jira and Salesforce examples are discussed',why='Turn an abstract access mechanism into a visible relationship among source, route and result; avoid a new diagram for every example',reuse_rule='For a mechanism involving sources and access paths, depict the route and the sources together, then hold while concrete examples are explained.',evidence='graphics-study/D3-connector-build.jpg'),
 dict(id='enumerate-distinct-needs',window=[1422,1455],anchor='first is',teaching_job='Enumerate distinct governance needs within one category',visual_family='aligned card family',entities=['baseline skills','custom workflows','skill-sharing controls'],relationships=['member of governance needs'],states=['Category tag established','Tag relocates to make room','Baseline card flips into place','Second card joins for custom workflows','Third card joins for sharing controls'],motion=['relocate category heading','turn card from edge-on to front-facing','add aligned siblings','hold established items'],timing_policy='Each card joins when its need is introduced, spread across the explanation rather than a rapid automatic three-card stagger',why='Give each need a stable place and equal status without losing the category that groups them',reuse_rule='For enumerated peer concepts, introduce one sibling per explanatory beat, using consistent scale and alignment. Choose a family-specific reveal separately.',evidence='graphics-study/D4-governance-card.jpg'),
 dict(id='advance-known-list',window=[1985,2000],anchor='Second is to model',teaching_job='Advance through previously established best practices',visual_family='fixed emphasis list',entities=['benchmark set','critical semantics','trusted assets','source access'],relationships=['next recommendation'],states=['First recommendation active','Second recommendation becomes active','Other items remain dimmed in their original positions'],motion=['discrete emphasis switch','hold geometry'],timing_policy='Switch near the start of the next recommendation; the inspected source switches at about 1989.733 seconds, after the segment-level transcript introduces Second around 1987 seconds',why='Indicate progress through a known structure without requiring the viewer to relearn its layout',reuse_rule='When advancing a known list, preserve positions and change emphasis. A new point does not automatically require a new scene or moving object.',evidence='graphics-study/D6-best-practice-focus.jpg')]
for ex in examples:
 a,z=ex['window'];ex['spoken_segments']=[{'start':int(s['startMs'])/1000,'end':int(s['endMs'])/1000,'text':s['text']} for s in tx if a<=int(s['startMs'])/1000<z];ex['confidence']={'graphic_observation':'observed in source frames','teaching_job_and_why':'interpretation of explanatory function; not a claim about creator intent or measured learning outcomes','timing':'source-frame timing where measured; transcript segment timestamps elsewhere, not frame-accurate word alignment'}
schema={'version':1,'purpose':'Learn reusable mappings from explanatory intent to graphic structure, state transitions and timing; do not infer animation from isolated keywords','event_contract':['spoken_span','teaching_job','known_context','entities','relationships','visual_family','previous_state','next_state','motion_operation','reveal_anchor','settle_and_hold','why','evidence_or_asset_requirements','confidence'],'pipeline':['segment transcript into explanatory beats','resolve entities, relationships and known viewer context','classify teaching function','choose visual representation and persistent objects','plan state changes and camera separately','align planned changes to the actual narration','render and compare explanatory clarity plus timing'],'examples':examples}
(root/'explanation-to-graphics.json').write_text(json.dumps(schema,indent=2))
lines=['# From explanation to graphics\n','This is an initial five-example annotation set linking the reference transcript to observed graphic behavior. It is a seed for a transcript-driven visual planner, not a trained model or a complete annotation of all 34 minutes.\n','The planning unit is an explanatory beat: what the viewer already knows, what changes in their understanding, and which visible state change makes that relationship clear.\n','| Spoken cue / section | Teaching job | Graphic and change | Why |\n|---|---|---|---|']
for e in examples:lines.append('| '+e['anchor']+' / '+str(e['window'])+'s | '+e['teaching_job']+' | '+e['visual_family']+': '+' → '.join(e['states'])+' | '+e['why']+' |')
lines+=['\n## Generation contract\n','For each beat: **spoken span → teaching purpose → entities/relationships → current visual state → next visual state → motion → narration anchor → hold duration → rationale**.\n','Semantic planning and animation style are separate. “Three components” suggests a decomposition or sibling group; the surrounding explanation determines whether a tree, cards, diagram focus or a list is appropriate. It does not specify a card flip.\n','Use recurring source patterns as examples, not universal rules. Preserve objects when the explanation continues the same model. Use motion to expose a new relationship, isolate a detail or show a state change. Keep the settled state while the speaker elaborates.\n','Exact export timing requires the actual narration and word alignment. Segment-level transcript timestamps and rendered source changes can differ; a transcript alone does not determine a frame-accurate edit.\n','Next annotation work: apply this event contract across the 27 reference sequences; mark explanation boundaries, known context, state changes, source evidence, exceptions, and uncertain mappings before treating them as generation rules.\n']
(root/'EXPLANATION-TO-GRAPHICS.md').write_text('\n'.join(lines));print('Saved five transcript-linked teaching/graphics examples and generation contract')
